let currentFile = null, questions = [], questionIndex = 0, lastChatSignature = '', chatSyncInFlight = false, healthData = null, eventSource = '', usageActivity = null, usageMode = 'daily', chatFiles = [], accessToken = sessionStorage.getItem('second_brain_token')||'', amapLoader = null, mapObserver = null;
