function renderMemoryRetry(el,id,attachments){if(!el)return;renderMemoryCandidates(el,attachments?.memory_candidates||[]);if(attachments?.memory_status!=='failed')return;const button=document.createElement('button');button.className='secondary small';button.type='button';button.textContent='重试保存记忆';button.onclick=async()=>{button.disabled=true;try{const result=await api(`/api/chats/${id}/retry-memory`,{method:'POST'});toast(result.saved?'记忆已保存':'保存仍失败，请检查文件权限');lastChatSignature='';await syncConversation(true)}catch(error){toast(error.message)}finally{button.disabled=false}};el.append(button)}

function renderMemoryCandidates(host,items){for(const item of items){const card=document.createElement('div');card.className='memory-warning';const label=document.createElement('p');label.textContent=`待确认记忆：${item.fact}`;const reason=document.createElement('small');reason.textContent=item.reason;card.append(label,reason);for(const [text,accept] of [['确认保存',true],['不保存',false]]){const button=document.createElement('button');button.type='button';button.className='secondary small';button.textContent=text;button.onclick=async()=>{card.querySelectorAll('button').forEach(b=>b.disabled=true);try{await api(`/api/memory-candidates/${item.id}/resolve`,{method:'POST',body:JSON.stringify({accept})});card.remove();toast(accept?'已确认并保存记忆':'已忽略这条记忆');lastChatSignature='';if($('#chat').classList.contains('active'))await syncConversation(true);if($('#memory').classList.contains('active'))await loadFiles()}catch(error){toast(error.message);card.querySelectorAll('button').forEach(b=>b.disabled=false)}};card.append(button)}host.append(card)}}

function greeting(now=new Date()){const hour=now.getHours();if(hour<5)return'夜深了。';if(hour<11)return'早上好。';if(hour<13)return'中午好。';if(hour<18)return'下午好。';return'晚上好。'}
function updateClock(){const now=new Date();$('#eyebrow').textContent=new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long',hour:'2-digit',minute:'2-digit',hour12:false}).format(now);if($('#today').classList.contains('active'))$('#page-title').textContent=greeting(now)}

function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
async function ensureAccessToken(){if(accessToken)return accessToken;const response=await fetch('/api/auth/local-token',{credentials:'same-origin'});if(!response.ok)throw new Error('本机访问令牌初始化失败');accessToken=(await response.json()).token;sessionStorage.setItem('second_brain_token',accessToken);return accessToken}
async function api(path, options={}){const token=await ensureAccessToken(),{headers={},...request}=options;const response=await fetch(path,{credentials:'same-origin',...request,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),'Authorization':`Bearer ${token}`,...headers}});if(!response.ok){const body=await response.json().catch(()=>({detail:'请求失败'})),detail=body.detail,message=Array.isArray(detail)?detail.map(item=>item.msg).join('；'):typeof detail==='object'?(detail.message||'请求失败'):detail;const error=new Error(message||'请求失败');if(detail&&typeof detail==='object'&&!Array.isArray(detail))Object.assign(error,detail);throw error}return response.json()}

const serviceLabels={running:'核心服务在线',paused:'核心服务已暂停',terminating:'核心服务正在终止',offline:'核心服务已终止'};
function renderServiceStatus(data){const state=data?.state||'offline',label=serviceLabels[state]||'核心服务状态未知',status=$('#service-status'),version=$('#app-version'),description=$('#service-description'),pause=$('#pause-service'),terminate=$('#terminate-service'),canControl=Boolean(data?.can_control);status.dataset.state=state;status.querySelector('b').textContent=label;version.textContent=data?.version?`v${data.version}`:'v—';if(description)description.textContent=state==='running'?'服务正在本机运行，可安全处理聊天、同步与定时任务。':state==='paused'?'服务已暂停：聊天、手机同步、上传和定时任务均已停止。':state==='terminating'?'正在关闭服务；网页将很快显示为离线。':'服务未运行。请使用桌面启动器再次启动。';if(pause){pause.disabled=!canControl||state==='terminating'||state==='offline';pause.textContent=state==='paused'?'恢复服务':'暂停服务';pause.dataset.action=state==='paused'?'resume':'pause'}if(terminate)terminate.disabled=!canControl||state==='terminating'||state==='offline'}
async function loadServiceStatus(){try{renderServiceStatus(await api('/api/service/status'))}catch(_){renderServiceStatus(null)}}
$('#pause-service').onclick=async()=>{const button=$('#pause-service'),action=button.dataset.action||'pause';button.disabled=true;try{const state=await api(`/api/service/${action}`,{method:'POST'});renderServiceStatus(state);toast(action==='pause'?'服务已暂停':'服务已恢复')}catch(error){toast(error.message);await loadServiceStatus()}};
$('#terminate-service').onclick=async()=>{if(!confirm('确定终止后台服务吗？聊天、手机同步和定时任务会停止；需要使用桌面启动器才能再次启动。'))return;const button=$('#terminate-service');button.disabled=true;try{renderServiceStatus({state:'terminating',version:$('#app-version').textContent.replace(/^v/,''),can_control:true});await api('/api/service/terminate',{method:'POST'});toast('正在终止服务…');setTimeout(loadServiceStatus,700)}catch(error){toast(error.message);await loadServiceStatus()}};

$$('.nav').forEach(button=>button.onclick=()=>{const id=button.dataset.view;$$('.nav,.view').forEach(el=>el.classList.remove('active'));button.classList.add('active');$('#'+id).classList.add('active');$('#page-title').textContent=id==='today'?greeting():titles[id];$('.sidebar').classList.remove('open');if(id==='goals')loadGoals();if(id==='memory')loadFiles();if(id==='inbox'){loadUploadHistory();loadInboxHistory()}if(id==='health')loadHealth();if(id==='safety')loadSafety();if(id==='settings'){loadUsage();loadProviders();loadEmailAccounts();loadPairedDevices();loadLocationSettings();loadWebSearchSettings();loadNotificationSettings()}if(id==='chat'){loadProviders();syncConversation(true)}});
