function idempotencyKey(){return window.crypto?.randomUUID?.()||`web-${Date.now()}-${Math.random().toString(16).slice(2)}`}
function goalStatusLabel(status){return({active:'推进中',paused:'已暂停',completed:'已完成',cancelled:'已取消'})[status]||status}
function taskStatusLabel(status){return({pending:'待开始',in_progress:'进行中',blocked:'受阻',completed:'已完成',cancelled:'已取消'})[status]||status}
function taskScheduleLabel(task){if(task.schedule==='once')return task.next_run_at?`一次 · ${task.next_run_at}`:'一次提醒';if(task.schedule==='interval')return `每 ${task.interval_minutes} 分钟`;if(task.schedule==='event')return `${task.event_source||'事件'}${task.event_kind?' · '+task.event_kind:''}`;return '手动'}
function toggleGoalForm(show){$('#goal-form').classList.toggle('hidden',!show);if(show)$('#goal-title').focus()}
$('#show-goal-form').onclick=()=>toggleGoalForm(true);
$('#cancel-goal-form').onclick=()=>{ $('#goal-form').reset();toggleGoalForm(false) };
$('#goal-form').onsubmit=async event=>{event.preventDefault();const form=$('#goal-form'),button=form.querySelector('[type="submit"]');button.disabled=true;try{await api('/api/goals',{method:'POST',headers:{'X-Idempotency-Key':idempotencyKey()},body:JSON.stringify({title:$('#goal-title').value.trim(),description:$('#goal-description').value.trim(),due_at:$('#goal-due-at').value||null})});form.reset();toggleGoalForm(false);toast('目标已创建');await loadGoals()}catch(error){toast(error.message)}finally{button.disabled=false}};
async function loadGoals(){const host=$('#goals-list');try{const data=await api('/api/goals?include_closed=true');host.innerHTML='';if(!data.goals.length){host.innerHTML='<article class="goal-empty"><b>还没有目标</b><p>从一个想持续推进的方向开始，例如“准备旅行”或“完成一门课程”。</p></article>';return}for(const goal of data.goals)host.append(renderGoal(goal))}catch(error){host.innerHTML=`<p class="muted">读取目标失败：${escapeHtml(error.message)}</p>`}}
function renderGoal(goal){const card=document.createElement('article');card.className='goal-card';const due=goal.due_at?`截止 ${escapeHtml(goal.due_at)}`:'未设截止日期';card.innerHTML=`<div class="goal-card-head"><div><span class="goal-status ${escapeHtml(goal.status)}">${escapeHtml(goalStatusLabel(goal.status))}</span><h3>${escapeHtml(goal.title)}</h3><p>${escapeHtml(goal.description||'还没有补充说明。')}</p></div><small>${due}<br>${goal.completed_task_count||0}/${goal.task_count||0} 项任务完成</small></div><div class="goal-tasks"></div><form class="task-form"><input class="task-title" maxlength="200" required placeholder="添加下一步任务"><select class="task-schedule" aria-label="运行方式"><option value="manual">手动</option><option value="once">一次提醒</option><option value="interval">周期提醒</option><option value="event">事件触发</option></select><input class="task-when" type="datetime-local" aria-label="首次运行时间"><input class="task-interval" type="number" min="1" value="1440" aria-label="间隔分钟"><select class="task-source" aria-label="事件来源"><option value="email">邮件</option><option value="sms">短信</option><option value="notification">通知</option><option value="calendar">日历</option><option value="file">文件</option><option value="health">健康</option></select><input class="task-kind" maxlength="120" placeholder="事件类型（可选）"><button class="secondary small" type="submit">添加</button></form><div class="goal-actions"></div><details class="goal-audit"><summary>活动记录</summary><div class="goal-events"><p class="muted">展开后加载…</p></div></details>`;const tasks=card.querySelector('.goal-tasks');const renderTasks=list=>{tasks.innerHTML='';if(!list.length){tasks.innerHTML='<p class="muted">把可执行的下一步写下来。</p>';return}for(const task of list){const row=document.createElement('div');row.className='goal-task '+task.status;row.innerHTML=`<button class="task-complete" type="button" aria-label="${escapeHtml(task.title)}" ${task.status==='completed'||task.status==='cancelled'?'disabled':''}>${task.status==='completed'?'✓':'○'}</button><span><b>${escapeHtml(task.title)}</b><small>${escapeHtml(taskStatusLabel(task.status))} · ${escapeHtml(taskScheduleLabel(task))}${task.next_run_at?' · 下次 '+escapeHtml(task.next_run_at):''}</small></span>${task.schedule!=='manual'?`<button class="task-toggle secondary small" type="button">${task.enabled?'暂停':'恢复'}</button>`:''}`;row.querySelector('.task-complete').onclick=async()=>{try{await api(`/api/tasks/${task.id}/status`,{method:'POST',body:JSON.stringify({status:task.status==='pending'?'in_progress':'completed'})});await loadGoals()}catch(error){toast(error.message)}};const toggle=row.querySelector('.task-toggle');if(toggle)toggle.onclick=async()=>{try{await api(`/api/tasks/${task.id}`,{method:'PUT',body:JSON.stringify({enabled:!task.enabled})});await loadGoals()}catch(error){toast(error.message)}};tasks.append(row)}};renderTasks(goal.tasks||[]);const form=card.querySelector('.task-form'),schedule=form.querySelector('.task-schedule'),syncFields=()=>{const type=schedule.value;form.querySelector('.task-when').hidden=!['once','interval'].includes(type);form.querySelector('.task-interval').hidden=type!=='interval';form.querySelector('.task-source').hidden=type!=='event';form.querySelector('.task-kind').hidden=type!=='event'};schedule.onchange=syncFields;syncFields();form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type="submit"]'),type=schedule.value,when=form.querySelector('.task-when').value;button.disabled=true;try{const payload={title:form.querySelector('.task-title').value.trim(),schedule:type};if(['once','interval'].includes(type)){if(!when)throw new Error('请选择首次运行时间');payload.next_run_at=new Date(when).toISOString()}if(type==='interval')payload.interval_minutes=Number(form.querySelector('.task-interval').value);if(type==='event'){payload.event_source=form.querySelector('.task-source').value;payload.event_kind=form.querySelector('.task-kind').value.trim()}await api(`/api/goals/${goal.id}/tasks`,{method:'POST',headers:{'X-Idempotency-Key':idempotencyKey()},body:JSON.stringify(payload)});await loadGoals()}catch(error){toast(error.message)}finally{button.disabled=false}};const actions=card.querySelector('.goal-actions');const choices=goal.status==='active'?[['paused','暂停'],['completed','完成'],['cancelled','取消']]:goal.status==='paused'?[['active','恢复'],['cancelled','取消']]:[];for(const [status,label] of choices){const button=document.createElement('button');button.className=status==='cancelled'?'danger-link':'secondary small';button.type='button';button.textContent=label;button.onclick=async()=>{if(status==='cancelled'&&!confirm(`取消目标“${goal.title}”？`))return;try{await api(`/api/goals/${goal.id}/status`,{method:'POST',body:JSON.stringify({status})});toast(`目标已${label}`);await loadGoals()}catch(error){toast(error.message)}};actions.append(button)}const details=card.querySelector('.goal-audit');details.ontoggle=async()=>{if(!details.open||details.dataset.loaded)return;try{const data=await api(`/api/activity?goal_id=${goal.id}&limit=30`),events=details.querySelector('.goal-events');events.innerHTML=data.activity.length?data.activity.map(item=>`<p><b>${escapeHtml(item.task_title)} · ${escapeHtml(item.status)}</b><small>${escapeHtml(item.started_at)}${item.error?' · '+escapeHtml(item.error):''}${item.next_run_at?' · 下次 '+escapeHtml(item.next_run_at):''}</small></p>`).join(''):'<p class="muted">暂无运行记录。</p>';details.dataset.loaded='true'}catch(error){details.querySelector('.goal-events').textContent=error.message}};return card}

$('#chat-file-input').onchange=event=>{chatFiles=[...chatFiles,...event.target.files].slice(0,10);event.target.value='';renderChatFileTray()};
function renderChatFileTray(){const tray=$('#chat-file-tray'),note=$('#chat-file-note');tray.classList.toggle('hidden',!chatFiles.length);note.classList.toggle('hidden',!chatFiles.length);tray.innerHTML=chatFiles.map((file,index)=>`<span><b>${escapeHtml(file.name)}</b><small>${formatBytes(file.size)}</small><button type="button" data-index="${index}" aria-label="移除 ${escapeHtml(file.name)}">×</button></span>`).join('');tray.querySelectorAll('button').forEach(button=>button.onclick=()=>{chatFiles.splice(Number(button.dataset.index),1);renderChatFileTray()})}
function formatBytes(size){if(size<1024)return size+' B';if(size<1024*1024)return(size/1024).toFixed(1)+' KB';return(size/1024/1024).toFixed(1)+' MB'}
async function uploadChatFiles(files){const uploaded=[];for(const file of files){const data=new FormData();data.append('file',file,file.name);uploaded.push(await api('/api/upload',{method:'POST',body:data}))}return uploaded}
$('#chat-form').onsubmit=async event=>{event.preventDefault();await sendCurrentChat()};
function resizeChatInput(){const input=$('#chat-input');input.style.height='auto';input.style.height=Math.min(input.scrollHeight,132)+'px';input.style.overflowY=input.scrollHeight>132?'auto':'hidden'}
$('#chat-input').addEventListener('input',resizeChatInput);resizeChatInput();
async function sendCurrentChat(retryPayload=null){const input=$('#chat-input'),note=$('#chat-file-note'),send=$('.send'),text=retryPayload?.message??input.value.trim(),files=retryPayload?[]:[...chatFiles];if((!text&&!files.length)||send.disabled)return;send.disabled=true;if(!retryPayload){input.value='';resizeChatInput()}let thinking=null,uploaded=[];try{uploaded=retryPayload?.uploaded||await uploadChatFiles(files);const userFiles=uploaded.map(file=>fileAttachment(file)),message=text||'请分析这些文件',fileNote=retryPayload?.file_note??note.value.trim();if(!retryPayload)appendMessage(message,'user',true,userFiles,[],fileNote);thinking=appendThinking();const selection=retryPayload?.selection||parseModelValue($('#chat-model').value),payload={message,file_hashes:uploaded.map(file=>file.hash),file_note:fileNote,...selection};const result=await streamChat(payload,thinking);thinking.stop(result.answer,result.attachments?.assistant_files||[],result.attachments?.links||[],result.attachments?.maps||[],result.attachments?.warnings||[],result.attachments?.guidance||inferGuidance(result.answer));const answerEl=$('#messages').lastElementChild;setTimeout(()=>renderMemoryRetry(answerEl,result.id,result.attachments),160);$('#sources').innerHTML=result.sources.map(s=>`<span>${escapeHtml(s)}</span>`).join('');note.value='';chatFiles=[];renderChatFileTray();lastChatSignature=''}catch(error){if(thinking)thinking.fail(error.message,error.retryable!==false,()=>sendCurrentChat({message:text,uploaded,file_note:retryPayload?.file_note??note.value.trim(),selection:retryPayload?.selection||parseModelValue($('#chat-model').value)}));else{if(!retryPayload){input.value=text;resizeChatInput()}toast('附件上传失败：'+error.message)}}finally{send.disabled=false;input.focus()}}
async function streamChat(payload,thinking){const token=await ensureAccessToken(),response=await fetch('/api/chat/stream',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`},body:JSON.stringify(payload)});if(!response.ok)throw new Error('流式连接失败');if(!response.body)throw new Error('浏览器不支持流式输出');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',answer='',result=null;while(true){const {value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const blocks=buffer.split('\n\n');buffer=blocks.pop()||'';for(const block of blocks){let event='message',data='';for(const line of block.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim()}if(!data)continue;const parsed=JSON.parse(data);if(event==='delta'){answer+=parsed.text;thinking.update(answer)}else if(event==='done')result=parsed;else if(event==='error'){const error=new Error(parsed.message||'请求失败');Object.assign(error,parsed);throw error}}if(done)break}if(!result)throw new Error('模型连接提前结束，请重试');return result}
function fileAttachment(file){const name=file.original_name||file.name||'附件',suffix=name.split('.').pop().toLowerCase(),images=['jpg','jpeg','png','webp','heic','heif','bmp','gif'],videos=['mp4','mov','m4v','avi','mkv','webm'];return{hash:file.hash,name,kind:images.includes(suffix)?'image':videos.includes(suffix)?'video':'document',url:`/api/files/${encodeURIComponent(file.hash)}/content`,summary:file.extracted_text||''}}
function appendMessage(text,role,animate=true,files=[],links=[],fileNote='',maps=[],warnings=[],guidance=null){const el=document.createElement('div');el.className='message '+role+(animate?'':' no-animation');const copy=document.createElement('div');copy.className='message-copy';if(role==='assistant')copy.innerHTML=renderMarkdown(text);else copy.textContent=text;el.append(copy);if(fileNote){const note=document.createElement('div');note.className='attachment-note';note.textContent='附件说明：'+fileNote;el.append(note)}renderMessageExtras(el,files,links,maps,warnings,guidance);$('#messages').append(el);if(animate)el.scrollIntoView({behavior:'smooth',block:'end'});return el}
function inferGuidance(text){const match=String(text||'').match(/要我[^“”"]{0,50}[“"]([^“”"]{2,60})[”"][^。！？!?]{0,24}(?:或者|还是|或)[“"]([^“”"]{2,60})[”"]/);return match?{question:'你想先怎么做？',options:[match[1],match[2]]}:null}
function collapseLegacyFollowups(text){const value=String(text||''),match=value.match(/要我[^“”"]{0,50}[“"]([^“”"]{2,60})[”"][^。！？!?]{0,24}(?:或者|还是|或)[“"]([^“”"]{2,60})[”"]/);if(!match)return value;const end=value.indexOf('？',match.index);return end<0?value:value.slice(0,end+1)}
function renderGuidance(el,guidance){if(!guidance?.question||!Array.isArray(guidance.options)||!guidance.options.length)return;const host=document.createElement('div');host.className='guided-choice';host.innerHTML=`<small>下一步 · ${escapeHtml(guidance.question)}</small><div class="guided-choice-options"></div>`;const options=host.querySelector('.guided-choice-options'),lock=()=>host.querySelectorAll('button').forEach(button=>button.disabled=true),choose=value=>{lock();sendCurrentChat({message:`针对你刚才的问题，我选择：${value}`})};for(const option of guidance.options.slice(0,6)){const button=document.createElement('button');button.type='button';button.textContent=option;button.onclick=()=>choose(option);options.append(button)}const other=document.createElement('button');other.type='button';other.textContent='其他…';other.onclick=()=>{other.disabled=true;const form=document.createElement('form');form.className='guided-other';form.innerHTML='<input maxlength="300" placeholder="输入你的答案"><button type="submit">继续</button>';form.onsubmit=event=>{event.preventDefault();const value=form.querySelector('input').value.trim();if(value)choose(value)};host.append(form);form.querySelector('input').focus()};options.append(other);el.append(host)}
function renderMessageExtras(el,files=[],links=[],maps=[],warnings=[],guidance=null){if(files.length){const gallery=document.createElement('div');gallery.className='message-files';for(const file of files){const item=document.createElement('a');item.className='message-file '+file.kind;item.href=file.url;item.target='_blank';item.rel='noopener';if(file.kind==='image')item.innerHTML=`<img src="${escapeHtml(file.url)}" alt="${escapeHtml(file.name)}" loading="lazy"><span>${escapeHtml(file.name)}</span>`;else if(file.kind==='video')item.innerHTML=`<video src="${escapeHtml(file.url)}" controls preload="metadata"></video><span>${escapeHtml(file.name)}</span>`;else item.innerHTML=`<i>↗</i><span>${escapeHtml(file.name)}</span>`;gallery.append(item)}el.append(gallery)}if(links.length){const cards=document.createElement('div');cards.className='message-links';cards.innerHTML=links.map(link=>`<a href="${escapeHtml(link.url)}" target="_blank" rel="noopener"><small>${escapeHtml(link.source||'官方链接')}</small><b>${escapeHtml(link.title)}</b><span>打开网页 ↗</span></a>`).join('');el.append(cards)}for(const spec of maps){const card=document.createElement('div');card.className='map-card';card.innerHTML=`<div class="map-canvas"></div><small>${escapeHtml(spec.query||spec.label||'位置')}</small>`;el.append(card);queueAmapRender(card.querySelector('.map-canvas'),spec)}for(const warning of warnings){const notice=document.createElement('div');notice.className='memory-warning';notice.textContent=warning;el.append(notice)}renderGuidance(el,guidance)}
async function loadAmap(){if(window.AMap)return window.AMap;if(amapLoader)return amapLoader;amapLoader=(async()=>{const config=await api('/api/map/config');if(!config.api_key)throw new Error('请先在设置中填写高德地图 Key');if(config.security_code)window._AMapSecurityConfig={securityJsCode:config.security_code};await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=`https://webapi.amap.com/maps?v=2.0&key=${encodeURIComponent(config.api_key)}`;script.onload=resolve;script.onerror=()=>reject(new Error('地图加载失败，请检查网络与 Key'));document.head.append(script)});return window.AMap})();return amapLoader}
async function renderAmap(host,spec){const AMap=await loadAmap(),center=spec.longitude!=null&&spec.latitude!=null?[spec.longitude,spec.latitude]:undefined,map=new AMap.Map(host,{zoom:13,center});if(center)new AMap.Marker({position:center,map,title:spec.label||'当前位置'});if(spec.query)AMap.plugin('AMap.PlaceSearch',()=>{const search=new AMap.PlaceSearch({map,pageSize:5});if(spec.mode==='nearby'&&center)search.searchNearBy(spec.query,center,5000);else search.search(spec.query)});return map}
function destroyRenderedMaps(){if(mapObserver){mapObserver.disconnect();mapObserver=null}for(const map of activeMaps){try{map.destroy?.()}catch(_){}}activeMaps.clear()}
function startAmapRender(host,spec){if(!host.isConnected||host.dataset.mapStarted)return;host.dataset.mapStarted='true';renderAmap(host,spec).then(map=>{if(host.isConnected)activeMaps.add(map);else map.destroy?.()}).catch(error=>{if(host.isConnected)host.innerHTML=`<p>${escapeHtml(error.message)}</p>`})}
function queueAmapRender(host,spec){if(!('IntersectionObserver' in window)){startAmapRender(host,spec);return}host._mapSpec=spec;if(!mapObserver)mapObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;mapObserver.unobserve(entry.target);startAmapRender(entry.target,entry.target._mapSpec)}},{rootMargin:'240px 0px'});mapObserver.observe(host)}
function appendThinking(){const el=document.createElement('div');el.className='message assistant thinking';el.innerHTML='<span class="codex-loader" aria-hidden="true"><i></i></span><span class="thought-text">正在思考</span>';$('#messages').append(el);el.scrollIntoView({behavior:'smooth'});return{update(text){el.classList.remove('thinking');el.innerHTML=`<div class="message-copy">${renderMarkdown(text)}</div>`;el.scrollIntoView({behavior:'smooth',block:'end'})},stop(text,files=[],links=[],maps=[],warnings=[],guidance=null){const settle=()=>{el.classList.remove('thinking','answering');el.classList.add('answer-arriving');el.innerHTML=`<div class="message-copy">${renderMarkdown(text)}</div>`;renderMessageExtras(el,files,links,maps,warnings,guidance);requestAnimationFrame(()=>el.classList.remove('answer-arriving'))};if(matchMedia('(prefers-reduced-motion: reduce)').matches)return settle();el.classList.add('answering');setTimeout(settle,100)},fail(text,retryable,retry){el.className='message assistant error-message';el.innerHTML=`<div class="message-copy">${escapeHtml(text)}</div>${retryable?'<button class="secondary retry-chat" type="button">重试</button>':''}`;const button=el.querySelector('.retry-chat');if(button)button.onclick=()=>{el.remove();retry()}}}}

async function syncConversation(force=false){if(!$('#chat').classList.contains('active')||$('.send').disabled||document.hidden||chatSyncInFlight)return;chatSyncInFlight=true;try{const state=await api('/api/chats/state');if(!force&&state.signature===lastChatSignature)return;const data=await api('/api/chats?limit=30'),items=[...data.chats].reverse();lastChatSignature=state.signature;const messages=$('#messages');destroyRenderedMaps();messages.innerHTML='';if(!items.length){appendMessage('有什么正在占用你的注意力？告诉我，我会结合你的记忆一起梳理。','assistant',false);return}for(const item of items){const extra=item.attachments||{},guidance=extra.guidance||inferGuidance(item.assistant_message),answer=guidance&&!extra.guidance?collapseLegacyFollowups(item.assistant_message):item.assistant_message;appendMessage(item.user_message,'user',false,extra.user_files||[],[],extra.file_note||'');appendMessage(answer||'这条对话未完成。请重新发送，或在“聊天记录”中删除它。','assistant',false,extra.assistant_files||[],extra.links||[],'',extra.maps||[],extra.warnings||[],guidance);renderMemoryRetry(messages.lastElementChild,item.id,extra)}messages.scrollTop=messages.scrollHeight}catch(_){}finally{chatSyncInFlight=false}}
setInterval(()=>syncConversation(false),5000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncConversation(false)});

$('#history-open').onclick=async()=>{await loadChatHistory();$('#history-dialog').showModal()};
$('#history-close').onclick=()=>$('#history-dialog').close();
async function loadChatHistory(){const q=$('#history-search').value.trim(),data=await api('/api/chats'+(q?'?q='+encodeURIComponent(q):'')),list=$('#chat-history');list.innerHTML=data.chats.length?data.chats.map(item=>`<article class="history-item"><time>${escapeHtml(item.created_at)}</time><b>${escapeHtml(item.title||item.user_message)}</b><p>${escapeHtml(item.assistant_message)}</p><div><label><input class="delete-memory" type="checkbox"> 同时删除关联记忆</label><button class="danger-link delete-chat" data-id="${item.id}">删除这条</button></div></article>`).join(''):'<p class="muted">没有匹配的聊天记录。</p>';$$('.delete-chat').forEach(button=>button.onclick=()=>deleteChat(button))}
$('#history-search-button').onclick=loadChatHistory;
$('#history-search').onkeydown=event=>{if(event.key==='Enter')loadChatHistory()};
async function deleteChat(button){const item=button.closest('.history-item'),deleteMemory=item.querySelector('.delete-memory').checked;if(!confirm(deleteMemory?'确定删除这条对话及其关联记忆吗？':'确定只删除这条聊天记录吗？'))return;const result=await api(`/api/chats/${button.dataset.id}`,{method:'DELETE',body:JSON.stringify({delete_memory:deleteMemory})});item.classList.add('removing');setTimeout(()=>item.remove(),180);toast(deleteMemory?`已删除聊天，并清理 ${result.removed_memories} 条关联记忆`:'已删除聊天记录')}

async function loadFiles(){const data=await api('/api/memory');$('#files').innerHTML=data.files.map(path=>`<button class="file-item ${path===currentFile?'active':''}" data-file="${escapeHtml(path)}">${escapeHtml(path)}</button>`).join('');$$('.file-item').forEach(el=>el.onclick=()=>openFile(el.dataset.file));const pending=$('#pending-memory');pending.replaceChildren();renderMemoryCandidates(pending,data.candidates||[])}
async function openFile(path){const data=await api('/api/memory/'+encodeURI(path));currentFile=path;$('#current-file').textContent=path;$('#memory-content').value=data.content;$('#save-memory').disabled=false;loadFiles()}
$('#save-memory').onclick=async()=>{try{await api('/api/memory/'+encodeURI(currentFile),{method:'PUT',body:JSON.stringify({content:$('#memory-content').value})});toast('记忆已保存')}catch(error){toast(error.message)}};
$('#search-button').onclick=async()=>{const q=$('#memory-search').value.trim();if(!q)return loadFiles();const data=await api('/api/search?q='+encodeURIComponent(q));$('#files').innerHTML=data.results.map(hit=>`<button class="file-item" data-file="${escapeHtml(hit.path)}">${escapeHtml(hit.path)} · ${hit.score}</button>`).join('');$$('.file-item').forEach(el=>el.onclick=()=>openFile(el.dataset.file))};

const drop=$('#dropzone'),fileInput=$('#file-input');['dragenter','dragover'].forEach(type=>drop.addEventListener(type,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(type=>drop.addEventListener(type,e=>{e.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>uploadFiles(e.dataTransfer.files));fileInput.onchange=()=>uploadFiles(fileInput.files);
async function uploadFiles(files){const list=[...files];if(!list.length)return;const output=$('#upload-result');output.innerHTML='';for(const file of list){const card=document.createElement('article');card.className='upload-card processing';card.innerHTML=`<b>${escapeHtml(file.name)}</b><span>正在归档与分析…</span>`;output.append(card);const data=new FormData();data.append('file',file,file.name);try{const result=await api('/api/upload',{method:'POST',body:data});renderUploadResult(card,result,file.name)}catch(error){card.classList.remove('processing');card.classList.add('error');card.innerHTML=`<b>${escapeHtml(file.name)}</b><span>${escapeHtml(error.message)}</span>`}}fileInput.value='';loadUploadHistory()}
function renderUploadResult(card,result,name){card.classList.remove('processing','error');const status=result.reanalyzed?'检测到上次分析失败，已用当前模型重新分析':result.duplicate?'文件已存在，显示上次分析结果':`已归档到 ${result.stored_path}`;card.innerHTML=`<b>${escapeHtml(name)}</b><span>${escapeHtml(status)}</span><p>${escapeHtml((result.extracted_text||'未提取到内容').slice(0,1000))}</p>${result.can_reanalyze?`<button class="secondary reanalyze" data-hash="${escapeHtml(result.hash)}">使用当前模型重新分析</button>`:''}`;const button=card.querySelector('.reanalyze');if(button)button.onclick=()=>reanalyzeFile(result.hash,card,name)}
async function reanalyzeFile(hash,card,name){card.classList.add('processing');const button=card.querySelector('.reanalyze');if(button)button.disabled=true;try{const result=await api(`/api/files/${encodeURIComponent(hash)}/reanalyze`,{method:'POST'});renderUploadResult(card,result,name);toast('已使用当前模型重新分析')}catch(error){card.classList.remove('processing');if(button)button.disabled=false;toast('重新分析失败：'+error.message)}}
async function loadUploadHistory(){const data=await api('/api/files?limit=100');$('#upload-history').innerHTML=data.files.length?data.files.map(file=>`<article class="upload-card"><b>${escapeHtml(file.original_name)}</b><span>${escapeHtml(file.created_at)}</span><p>${escapeHtml((file.extracted_text||'暂无分析结果').slice(0,500))}</p><button class="danger-link delete-upload" data-hash="${escapeHtml(file.hash)}" data-name="${escapeHtml(file.original_name)}">删除记录和原件</button></article>`).join(''):'<p class="muted">还没有上传记录。</p>';$$('.delete-upload').forEach(button=>button.onclick=()=>deleteUpload(button))}
async function deleteUpload(button){if(!confirm(`确定删除“${button.dataset.name}”的记录和归档原件吗？此操作无法撤销。`))return;await api(`/api/files/${encodeURIComponent(button.dataset.hash)}`,{method:'DELETE'});toast('文件已删除');await loadUploadHistory()}
$('#refresh-uploads').onclick=loadUploadHistory;

