async function loadInboxHistory(){const query=eventSource?`?source=${encodeURIComponent(eventSource)}&limit=200`:'?limit=200';const data=await api('/api/events'+query);const counts={email:0,sms:0,notification:0,calendar:0};data.events.forEach(item=>{counts[item.source]=(counts[item.source]||0)+1});const max=Math.max(1,...Object.values(counts));const labels={email:'邮件',sms:'短信',notification:'通知',calendar:'日程'};$('#inbox-overview').innerHTML=Object.entries(counts).map(([source,count])=>`<div><span>${labels[source]||source}</span><b>${count}</b><i><em style="width:${count/max*100}%"></em></i></div>`).join('');$('#event-timeline').innerHTML=data.events.length?data.events.map(renderEvent).join(''):'<p class="muted">这个分类还没有采集记录。</p>'}
function renderEvent(item){const payload=item.payload||{},labels={email:'邮件',sms:'短信',notification:'通知',calendar:'日程'},title=payload.subject||payload.title||payload.merchant||payload.sender||item.kind||'已采集内容',detail=payload.summary||payload.raw||payload.text||payload.package||eventKindLabel(item.kind),body=payload.body||'',attachments=payload.attachments||[];const attachmentHtml=attachments.length?`<div class="email-attachments">${attachments.map(file=>file.url?`<a href="${escapeHtml(file.url)}" target="_blank" rel="noopener">${escapeHtml(file.name||'附件')} ↗</a>`:`<span>${escapeHtml(file.name||'附件')} · ${escapeHtml(file.reason||'未读取')}</span>`).join('')}</div>`:'';const bodyHtml=body?`<details class="email-content"><summary>查看邮件正文</summary><div>${escapeHtml(body)}</div>${attachmentHtml}</details>`:attachmentHtml;return `<article class="event-item"><span class="event-dot ${escapeHtml(item.source)}"></span><div><time>${escapeHtml(item.created_at)}</time><b>${escapeHtml(title)}</b><p>${escapeHtml(detail||'已处理')}</p>${bodyHtml}</div><small>${escapeHtml(labels[item.source]||item.source)} · ${escapeHtml(eventKindLabel(item.kind))}</small></article>`}
function eventKindLabel(kind){return ({expense:'消费',pickup:'快递',health_appointment:'健康提醒',unknown:'待整理',ignored:'已忽略'}[kind]||kind||'记录')}

