$('#provider-form').onsubmit=async e=>{e.preventDefault();const name=$('#provider-name').value.trim(),models=$('#provider-model').value.split(/[,，]/).map(x=>x.trim()).filter(Boolean);if(!name||!models.length)return toast('请填写显示名称和至少一个模型');await api('/api/providers',{method:'POST',body:JSON.stringify({name,base_url:$('#provider-url').value,api_key:$('#provider-key').value,models,consumption_level:$('#provider-consumption').value})});$('#provider-key').value='';$('#provider-model').value='';toast('供应商与消耗程度已保存');await loadProviders()};
function modelValue(provider,model){return `${provider}::${model}`}
function parseModelValue(value){if(!value)return{};const [provider,...rest]=value.split('::');return{provider,model:rest.join('::')}}
async function loadProviders(){const data=await api('/api/providers');const options=data.providers.flatMap(provider=>provider.models.map(model=>({provider:provider.name,model,value:modelValue(provider.name,model)})));const optionHtml=options.map(item=>`<option value="${escapeHtml(item.value)}">${escapeHtml(item.provider)} · ${escapeHtml(item.model)}</option>`).join('');const currentChat=$('#chat-model').value;$('#chat-model').innerHTML='<option value="">默认 · 文字处理路由</option>'+optionHtml;$('#chat-model').value=currentChat;for(const [id,task,label] of [['text-route','smart','尚未配置'],['vision-route','vision','尚未配置'],['video-route','video','未配置时使用图片模型']]){const select=$('#'+id),route=data.routes.find(item=>item.task===task);select.innerHTML=`<option value="">${label}</option>`+optionHtml;if(route)select.value=modelValue(route.provider,route.model)}const levels={low:'小消耗',medium:'中消耗',high:'大消耗'};$('#provider-list').innerHTML=data.providers.length?data.providers.map(p=>`<article class="provider-entry"><div class="provider-title"><span class="provider-info"><b>${escapeHtml(p.name)} · ${levels[p.consumption_level]||'中消耗'}</b><small>${p.models.map(escapeHtml).join(' · ')}</small></span><button class="danger-link delete-provider" data-id="${p.id}" data-name="${escapeHtml(p.name)}">删除</button></div><div class="price-list">${p.models.map(model=>renderPriceRow(p,model)).join('')}</div></article>`).join(''):'<p class="muted">还没有供应商</p>';$$('.delete-provider').forEach(button=>button.onclick=()=>deleteProvider(button.dataset.id,button.dataset.name));$$('.save-price').forEach(button=>button.onclick=()=>saveModelPrice(button))}
function renderPriceRow(provider,model){const price=provider.prices?.[model]||{},currency=price.currency||'CNY';return `<div class="price-row" data-provider="${escapeHtml(provider.name)}" data-model="${escapeHtml(model)}"><b>${escapeHtml(model)}</b><label>输入价<input class="input-price" type="number" min="0" step="0.001" value="${Number(price.input_per_million||0)}"></label><label>输出价<input class="output-price" type="number" min="0" step="0.001" value="${Number(price.output_per_million||0)}"></label><label>币种<select class="price-currency"><option value="CNY" ${currency==='CNY'?'selected':''}>人民币</option><option value="USD" ${currency==='USD'?'selected':''}>美元</option></select></label><button class="secondary small save-price" type="button">保存价格</button><small>单位：每百万 Token</small></div>`}
async function saveModelPrice(button){const row=button.closest('.price-row');await api('/api/model-prices',{method:'POST',body:JSON.stringify({provider:row.dataset.provider,model:row.dataset.model,input_per_million:Number(row.querySelector('.input-price').value),output_per_million:Number(row.querySelector('.output-price').value),currency:row.querySelector('.price-currency').value})});toast('模型价格已保存，历史费用已重算');await loadUsage()}
