async function loadLocationSettings(){const data=await api('/api/location/settings');$('#location-enabled').checked=data.enabled;$('#default-location').value=data.default?.label||'';$('#default-latitude').value=data.default?.latitude??'';$('#default-longitude').value=data.default?.longitude??'';const active=data.sources.filter(item=>item.enabled);$('#location-status').textContent=data.enabled?(active.length?`已开启 · ${active.map(item=>`${item.source}:${item.label||item.latitude+','+item.longitude}`).join('；')}`:'已开启，等待你主动保存位置'):'位置功能已关闭';$('#map-key').placeholder=data.has_map_api_key?'已加密保存；留空保持不变':'填写高德 Web(JS API) Key';$('#map-security-code').placeholder=data.has_map_security_code?'已加密保存；留空保持不变':'填写 securityJsCode';$('#map-web-service-key').placeholder=data.has_map_web_service_key?'已加密保存；留空保持不变':'需单独创建高德 Web 服务 Key'}
