async function loadPairedDevices(){const data=await api('/api/auth/devices'),host=$('#paired-devices');host.innerHTML=data.devices.length?data.devices.map(device=>`<div><span class="provider-info"><b>${escapeHtml(device.name)}</b><small>${device.last_used_at?'最近使用 '+escapeHtml(device.last_used_at):'尚未使用'} · 配对于 ${escapeHtml(device.created_at)}</small></span><button class="danger-link revoke-device" data-id="${device.id}" data-name="${escapeHtml(device.name)}">撤销</button></div>`).join(''):'<p class="muted">还没有已配对设备。</p>';$$('.revoke-device').forEach(button=>button.onclick=()=>revokeDevice(button.dataset.id,button.dataset.name))}
async function revokeDevice(id,name){if(!confirm(`撤销“${name}”的访问权限吗？撤销后需要重新配对。`))return;await api(`/api/auth/devices/${id}`,{method:'DELETE'});toast(`已撤销 ${name}`);await loadPairedDevices()}
async function loadUsage(){const [data,settings,activity]=await Promise.all([api('/api/usage'),api('/api/cost-settings'),api('/api/usage/activity?days=365')]);usageActivity=activity;const totals=activity.totals;$('#tokens').textContent=(Number(totals.prompt_tokens)+Number(totals.completion_tokens)).toLocaleString('zh-CN');$('#cost').textContent='¥'+Number(totals.estimated_cost).toFixed(4);$('#usd-cny-rate').value=Number(settings.usd_cny_rate).toFixed(2);$('#cost-breakdown').innerHTML=data.breakdown.length?data.breakdown.map(item=>`<div><span><b>${escapeHtml(item.provider||'未知')}</b><small>${escapeHtml(item.model||'未知模型')} · ${(Number(item.prompt_tokens)+Number(item.completion_tokens)).toLocaleString('zh-CN')} tokens</small></span><strong>¥${Number(item.estimated_cost).toFixed(4)}</strong></div>`).join(''):'<p class="muted">还没有模型调用记录。</p>';renderTokenActivity()}
function activityScale(items){const values=[...new Set(items.map(item=>Number(item.total_tokens)||0).filter(value=>value>0))].sort((a,b)=>a-b);if(!values.length)return()=>0;if(values.length===1)return value=>value>0?2:0;if(values.length===2)return value=>value<=0?0:value<=values[0]?2:3;if(values.length===3)return value=>value<=0?0:value<=values[0]?1:value<=values[1]?2:3;return value=>{if(value<=0)return 0;const rank=values.findIndex(item=>item>=value)/(values.length-1);return rank<.25?1:rank<.5?2:rank<.75?3:4}}
function activityTitle(item,label=item.date){return `${label} · ${Number(item.total_tokens).toLocaleString('zh-CN')} tokens · ¥${Number(item.estimated_cost||0).toFixed(4)}`}
function aggregateActivity(items,keyFor){const groups=new Map();items.forEach(item=>{const key=keyFor(item);const current=groups.get(key)||{date:key,total_tokens:0,estimated_cost:0};current.total_tokens+=Number(item.total_tokens);current.estimated_cost+=Number(item.estimated_cost);groups.set(key,current)});return [...groups.values()]}
function renderTokenActivity(){if(!usageActivity)return;const host=$('#token-activity'),days=usageActivity.days;if(usageMode==='daily'){const first=new Date(days[0].date+'T00:00:00'),firstOffset=(first.getDay()+6)%7,level=activityScale(days),months=[],seen=new Set();const cells=days.map((item,index)=>{const date=new Date(item.date+'T00:00:00'),week=Math.floor((firstOffset+index)/7)+1,weekday=(date.getDay()+6)%7+2,key=item.date.slice(0,7);if(!seen.has(key)){seen.add(key);months.push({label:`${date.getMonth()+1}月`,week})}return `<i class="activity-cell level-${level(item.total_tokens)}" style="grid-column:${week};grid-row:${weekday}" title="${escapeHtml(activityTitle(item))}"></i>`}).join('');host.innerHTML=`<div class="activity-scroll"><div class="daily-grid"><span class="weekday monday">一</span><span class="weekday wednesday">三</span><span class="weekday friday">五</span>${months.map(item=>`<span class="month-label" style="grid-column:${item.week}">${item.label}</span>`).join('')}${cells}</div></div><p class="activity-caption">颜色按当前 365 天内的非零用量分位分档；只有一两个活跃日时使用中间色阶。</p>`;return}if(usageMode==='weekly'){const weeks=aggregateActivity(days,item=>{const date=new Date(item.date+'T00:00:00'),monday=new Date(date);monday.setDate(date.getDate()-((date.getDay()+6)%7));return monday.toISOString().slice(0,10)}),level=activityScale(weeks);host.innerHTML=`<div class="period-grid weekly-grid">${weeks.map((item,index)=>`<div class="period-item"><i class="level-${level(item.total_tokens)}" title="${escapeHtml(activityTitle(item,'第 '+(index+1)+' 周'))}"></i><span>${index%8===0?index+1:''}</span></div>`).join('')}</div><p class="activity-caption">最近 ${weeks.length} 周 · 按非零周用量的分位区间着色</p>`;return}const months=aggregateActivity(days,item=>item.date.slice(0,7)).slice(-12),max=Math.max(...months.map(item=>item.total_tokens),0);host.innerHTML=`<div class="cumulative-chart">${months.map(item=>`<div class="cumulative-column" title="${escapeHtml(activityTitle(item,item.date))}"><strong>${item.total_tokens?compactTokens(item.total_tokens):'0'}</strong><i style="height:${max?Math.max(5,item.total_tokens/max*100):0}%"></i><span>${Number(item.date.slice(5))}月</span></div>`).join('')}</div><p class="activity-caption">最近 12 个月合计 · 柱高表示每月 Token 总量</p>`}
function compactTokens(value){if(value>=1000000)return(value/1000000).toFixed(1)+'M';if(value>=1000)return(value/1000).toFixed(1)+'K';return String(value)}
