async function loadHealth(){healthData=await api('/api/health/summary?days=14');const available=healthData.series.filter(item=>item.latest!==null);$('#health-metrics').innerHTML=available.length?available.slice(0,4).map(item=>`<article><span>${escapeHtml(item.label)}</span><strong>${formatHealthValue(item.latest,item.metric)}</strong><small>${escapeHtml(item.unit)} · 最近记录</small></article>`).join(''):'<article class="health-welcome"><span>暂无数据</span><strong>—</strong><small>从右上角导入 Apple 健康或小米运动数据</small></article>';const select=$('#health-metric'),previous=select.value;select.innerHTML=healthData.series.map(item=>`<option value="${item.metric}" ${item.latest===null?'disabled':''}>${escapeHtml(item.label)}</option>`).join('');select.value=available.some(item=>item.metric===previous)?previous:(available[0]?.metric||'steps');$('#health-import-status').textContent=healthData.sample_count?`本机已有 ${healthData.sample_count} 条近期样本 · ${healthData.sources.map(item=>item.name).join('、')}`:'尚未导入健康数据';drawHealthChart()}
function formatHealthValue(value,metric){if(value===null||value===undefined)return'—';if(metric==='steps')return Math.round(value).toLocaleString('zh-CN');return Number(value).toFixed(metric==='weight'?1:1)}
function drawHealthChart(){if(!healthData)return;const series=healthData.series.find(item=>item.metric===$('#health-metric').value),canvas=$('#health-chart'),empty=$('#health-empty');if(!series||series.values.every(value=>value===null)){canvas.classList.add('hidden');empty.classList.remove('hidden');return}canvas.classList.remove('hidden');empty.classList.add('hidden');$('#health-chart-title').textContent=series.label+'趋势';const wrap=canvas.parentElement,width=Math.max(320,wrap.clientWidth),height=280,dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;canvas.style.width=width+'px';canvas.style.height=height+'px';const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,width,height);const pad={left:46,right:20,top:25,bottom:38},values=series.values.filter(value=>value!==null),min=Math.min(...values),max=Math.max(...values),range=max-min||Math.max(1,max*.15),x=index=>pad.left+index*(width-pad.left-pad.right)/(series.values.length-1),y=value=>pad.top+(max-value)*(height-pad.top-pad.bottom)/range;ctx.strokeStyle='#ddd8cc';ctx.lineWidth=1;ctx.fillStyle='#7a817b';ctx.font='10px -apple-system,sans-serif';for(let row=0;row<4;row++){const yy=pad.top+row*(height-pad.top-pad.bottom)/3;ctx.beginPath();ctx.moveTo(pad.left,yy);ctx.lineTo(width-pad.right,yy);ctx.stroke();const label=max-row*range/3;ctx.fillText(formatHealthValue(label,series.metric),2,yy+3)}ctx.strokeStyle='#315d49';ctx.lineWidth=2;ctx.lineJoin='round';ctx.beginPath();let started=false;series.values.forEach((value,index)=>{if(value===null){started=false;return}if(!started){ctx.moveTo(x(index),y(value));started=true}else ctx.lineTo(x(index),y(value))});ctx.stroke();ctx.fillStyle='#d78042';series.values.forEach((value,index)=>{if(value===null)return;ctx.beginPath();ctx.arc(x(index),y(value),3,0,Math.PI*2);ctx.fill()});ctx.fillStyle='#7a817b';healthData.dates.forEach((day,index)=>{if(index%3===0||index===healthData.dates.length-1)ctx.fillText(day.slice(5),x(index)-12,height-12)})}
function inlineMarkdown(value){let html=escapeHtml(value);html=html.replace(/`([^`\n]+)`/g,'<code>$1</code>');html=html.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');html=html.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/__([^_]+)__/g,'<strong>$1</strong>');html=html.replace(/~~([^~]+)~~/g,'<del>$1</del>');html=html.replace(/(^|[^*])\*([^*\n]+)\*/g,'$1<em>$2</em>');return html}
function tableCells(line){return line.trim().replace(/^\||\|$/g,'').split('|').map(cell=>cell.trim())}
function renderMarkdown(value){const lines=String(value||'').replace(/\r\n?/g,'\n').split('\n'),out=[];let index=0;while(index<lines.length){const line=lines[index];if(/^```/.test(line)){const language=escapeHtml(line.slice(3).trim()),code=[];index++;while(index<lines.length&&!/^```/.test(lines[index]))code.push(lines[index++]);if(index<lines.length)index++;out.push(`<pre><code${language?` data-language="${language}"`:''}>${escapeHtml(code.join('\n'))}</code></pre>`);continue}if(!line.trim()){index++;continue}const heading=line.match(/^(#{1,6})\s+(.+)$/);if(heading){const level=Math.min(6,heading[1].length+1);out.push(`<h${level}>${inlineMarkdown(heading[2])}</h${level}>`);index++;continue}if(index+1<lines.length&&line.includes('|')&&/^\s*\|?\s*:?-{3,}/.test(lines[index+1])){const headers=tableCells(line);index+=2;const rows=[];while(index<lines.length&&lines[index].includes('|')&&lines[index].trim())rows.push(tableCells(lines[index++]));out.push(`<div class="markdown-table-wrap"><table><thead><tr>${headers.map(cell=>`<th>${inlineMarkdown(cell)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${inlineMarkdown(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);continue}const list=line.match(/^\s*([-*+] |\d+\. )(.+)$/);if(list){const ordered=/\d/.test(list[1]),items=[];while(index<lines.length){const match=lines[index].match(/^\s*([-*+] |\d+\. )(.+)$/);if(!match||/\d/.test(match[1])!==ordered)break;items.push(`<li>${inlineMarkdown(match[2])}</li>`);index++}out.push(`<${ordered?'ol':'ul'}>${items.join('')}</${ordered?'ol':'ul'}>`);continue}if(/^>\s?/.test(line)){const quotes=[];while(index<lines.length&&/^>\s?/.test(lines[index]))quotes.push(lines[index++].replace(/^>\s?/,''));out.push(`<blockquote>${quotes.map(inlineMarkdown).join('<br>')}</blockquote>`);continue}if(/^\s*([-*_])(?:\s*\1){2,}\s*$/.test(line)){out.push('<hr>');index++;continue}const paragraph=[line];index++;while(index<lines.length&&lines[index].trim()&&!/^(#{1,6})\s|^```|^\s*([-*+] |\d+\. )|^>\s?/.test(lines[index])&&!(index+1<lines.length&&lines[index].includes('|')&&/^\s*\|?\s*:?-{3,}/.test(lines[index+1])))paragraph.push(lines[index++]);out.push(`<p>${paragraph.map(inlineMarkdown).join('<br>')}</p>`)}return out.join('')}
const approvalStatusLabels={pending:'等待确认',approved:'已允许，等待执行',denied:'已拒绝',expired:'已过期',revoked:'已撤销',executing:'正在执行',executed:'已执行',failed:'执行失败'};
const actionLevelLabels={read:'读取',draft:'草稿',write:'外部写入',irreversible:'不可逆'};
async function loadSafety(){await Promise.all([loadApprovals(),loadConnectorPermissions(),loadAudit()])}
async function loadApprovals(){const host=$('#approval-list');try{const data=await api('/api/approvals?limit=100'),pending=data.approvals.filter(item=>item.status==='pending');$('#pending-approval-count').textContent=pending.length;host.innerHTML='';if(!data.approvals.length){host.innerHTML='<article class="safety-empty"><b>没有待处理动作</b><p>需要写入外部系统或删除数据时，审批卡会出现在这里。</p></article>';return}for(const item of data.approvals)host.append(renderApproval(item))}catch(error){host.innerHTML=`<p class="muted">读取审批失败：${escapeHtml(error.message)}</p>`}}
function renderApproval(item){const card=document.createElement('article');card.className=`approval-card ${item.status}`;const editable=item.status==='pending',payload=JSON.stringify(item.exact_payload||{},null,2);card.innerHTML=`<div class="approval-top"><span class="risk-badge ${escapeHtml(item.level)}">${escapeHtml(actionLevelLabels[item.level]||item.level)}</span><span class="approval-status">${escapeHtml(approvalStatusLabels[item.status]||item.status)}</span></div><h3>${escapeHtml(item.summary)}</h3><p>${escapeHtml(item.target||'未指定影响对象')}</p><dl><div><dt>连接器</dt><dd>${escapeHtml(item.connector||'本机数据')}</dd></div><div><dt>有效期</dt><dd>${escapeHtml(item.expires_at)}</dd></div></dl><label>将写入或处理的精确内容<textarea class="approval-payload" rows="5" ${editable?'':'readonly'}>${escapeHtml(payload)}</textarea></label><div class="approval-actions"></div>`;const actions=card.querySelector('.approval-actions');if(item.status==='pending'){for(const [decision,label,klass] of [['approve','允许','primary'],['deny','拒绝','danger-button'],['revoke','撤销','secondary']]){const button=document.createElement('button');button.type='button';button.className=klass+' small';button.textContent=label;button.onclick=async()=>{button.disabled=true;try{let edited_payload;if(decision==='approve'){try{edited_payload=JSON.parse(card.querySelector('textarea').value)}catch(_){throw new Error('精确内容不是合法 JSON')}}await api(`/api/approvals/${item.id}/decision`,{method:'POST',body:JSON.stringify({decision,edited_payload})});toast(label+'成功');await loadSafety()}catch(error){toast(error.message);button.disabled=false}};actions.append(button)}}else if(item.status==='approved'&&item.action_type==='data.forget'){const button=document.createElement('button');button.type='button';button.className='danger-button small';button.textContent='执行已批准的遗忘';button.onclick=async()=>{if(!confirm('这是不可逆操作。确定按审批卡中的精确内容执行遗忘吗？'))return;button.disabled=true;try{const result=await api(`/api/forget/${item.id}/execute`,{method:'POST'});toast(`已清理 ${result.removed_memory_lines} 条记忆，取消 ${result.cancelled_future_tasks} 个未来任务`);await loadSafety()}catch(error){toast(error.message);button.disabled=false}};actions.append(button)}else if(item.status==='approved'){const button=document.createElement('button');button.type='button';button.className='secondary small';button.textContent='撤销批准';button.onclick=async()=>{try{await api(`/api/approvals/${item.id}/decision`,{method:'POST',body:JSON.stringify({decision:'revoke'})});await loadSafety()}catch(error){toast(error.message)}};actions.append(button)}return card}
async function loadConnectorPermissions(){const host=$('#connector-permissions');try{const data=await api('/api/connectors/permissions');$('#connector-count').textContent=data.connectors.filter(item=>item.enabled).length;host.innerHTML='';const select=$('#audit-connector'),selected=select.value;select.innerHTML='<option value="">全部连接器</option>'+data.connectors.map(item=>`<option value="${escapeHtml(item.connector)}">${escapeHtml(item.display_name)}</option>`).join('');select.value=selected;for(const item of data.connectors){const card=document.createElement('article');card.className='connector-card';card.innerHTML=`<div><span class="connector-state ${item.enabled?'enabled':'revoked'}">${item.enabled?'已启用':'已撤销'}</span><h3>${escapeHtml(item.display_name)}</h3><p>${(item.scopes||[]).map(scope=>`<code>${escapeHtml(scope)}</code>`).join(' ')}</p><small>模式：${escapeHtml(item.mode)} · 最近使用：${escapeHtml(item.last_used_at||'从未')}</small></div><button class="${item.enabled?'danger-button':'secondary'} small" type="button">${item.enabled?'撤销':'重新启用'}</button>`;card.querySelector('button').onclick=async()=>{if(item.enabled&&!confirm(`撤销“${item.display_name}”后，相关同步和事件任务会立即停止。已有原始数据不会删除。继续吗？`))return;try{await api(`/api/connectors/permissions/${encodeURIComponent(item.connector)}`,{method:'PUT',body:JSON.stringify({enabled:!item.enabled})});toast(item.enabled?'权限已撤销':'权限已启用');await loadSafety()}catch(error){toast(error.message)}};host.append(card)}}catch(error){host.innerHTML=`<p class="muted">读取连接器失败：${escapeHtml(error.message)}</p>`}}
function auditQuery(){const params=new URLSearchParams(),connector=$('#audit-connector').value,from=$('#audit-from').value,to=$('#audit-to').value;if(connector)params.set('connector',connector);if(from)params.set('date_from',from);if(to)params.set('date_to',to+'T23:59:59');return params.toString()}
async function loadAudit(){const host=$('#audit-list');try{const data=await api('/api/audit?'+auditQuery());$('#audit-integrity').textContent=data.integrity.valid?'完整':'异常';$('#audit-integrity').className=data.integrity.valid?'integrity-ok':'integrity-bad';host.innerHTML=data.audit.length?data.audit.map(item=>`<article><time>${escapeHtml(item.created_at)}</time><div><b>${escapeHtml(item.event_type)}</b><p>${escapeHtml(item.connector||'本机')} · ${escapeHtml(item.actor)}</p></div><code>${escapeHtml(item.event_hash.slice(0,12))}</code></article>`).join(''):'<p class="muted">没有匹配的审计记录。</p>'}catch(error){host.innerHTML=`<p class="muted">读取审计失败：${escapeHtml(error.message)}</p>`}}
$('#refresh-safety').onclick=()=>loadSafety();
$('#audit-filters').onsubmit=event=>{event.preventDefault();loadAudit()};
$('#export-audit').onclick=async()=>{try{const data=await api('/api/audit/export?'+auditQuery()),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='second-brain-audit.json';link.click();URL.revokeObjectURL(url)}catch(error){toast(error.message)}};
$('#forget-form').onsubmit=async event=>{event.preventDefault();const phrase=$('#forget-phrase').value.trim();if(!phrase)return;try{await api('/api/forget',{method:'POST',headers:{'X-Idempotency-Key':idempotencyKey()},body:JSON.stringify({phrase})});$('#forget-form').reset();toast('遗忘请求已生成，请检查并批准审批卡');await loadSafety();$('#approval-list').scrollIntoView({behavior:'smooth'})}catch(error){toast(error.message)}};

function escapeHtml(value){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
updateClock();setInterval(updateClock,30000);
applyTheme(localStorage.getItem('second_brain_theme')||'system');
loadServiceStatus();setInterval(loadServiceStatus,10000);
loadProviders().catch(()=>{});
loadProfileStatus().catch(()=>{});
loadLatestMorning().catch(()=>{});
